begin;create extension if not exists pgtap with schema extensions;select plan(25);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','f0000000-0000-0000-0000-000000000001','authenticated','authenticated','send-a@example.test','',now(),'{}','{}',now(),now()),('00000000-0000-0000-0000-000000000000','f0000000-0000-0000-0000-000000000002','authenticated','authenticated','send-b@example.test','',now(),'{}','{}',now(),now());
insert into public.organizations(id,public_id,name)values('f1000000-0000-0000-0000-000000000001','org_deliveryaaaaaaaa','Delivery A'),('f1000000-0000-0000-0000-000000000002','org_deliverybbbbbbbb','Delivery B');
insert into public.organization_memberships(id,organization_id,user_id,role,status)values('f2000000-0000-0000-0000-000000000001','f1000000-0000-0000-0000-000000000001','f0000000-0000-0000-0000-000000000001','owner','active'),('f2000000-0000-0000-0000-000000000002','f1000000-0000-0000-0000-000000000002','f0000000-0000-0000-0000-000000000002','owner','active');
insert into public.contacts(id,organization_id,created_by_membership_id,assigned_membership_id,first_name,last_name,primary_email,source,lifecycle_status,marketing_email_status)values('f3000000-0000-0000-0000-000000000001','f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Ada','Eligible','Ada@Example.Test','Pack5','nurture','opted-in'),('f3000000-0000-0000-0000-000000000002','f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Opal','Out','out@example.test','Pack5','nurture','opted-out'),('f3000000-0000-0000-0000-000000000003','f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Sue','Suppressed','supp@example.test','Pack5','nurture','suppressed');
set local role authenticated;select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000001',true);
insert into public.contact_segments(organization_id,created_by_membership_id,name,criteria)values('f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Pack 5','{"version":1,"combinator":"and","rules":[{"field":"source","operator":"is","value":"Pack5"}]}');
insert into public.marketing_campaigns(organization_id,created_by_membership_id,name,subject,sender_name,reply_to,audience_type,audience_public_id,status,content)values('f1000000-0000-0000-0000-000000000001','f2000000-0000-0000-0000-000000000001','Safe send','Hello','Alex','alex@example.test','segment',(select public_id from public.contact_segments where name='Pack 5'),'ready','{"version":1,"heading":"Hi","body":"Body","ctaLabel":"","ctaUrl":"","footer":"Footer"}');
select is((public.confirm_campaign_send((select public_id from public.marketing_campaigns),'1234567890abcdef',true)).eligible_count,1,'only opted-in snapshotted');
select is((select matching_count from public.marketing_send_runs),3,'audience count stored');select is((select opted_out_count from public.marketing_send_runs),1,'opt-out count stored');select is((select suppressed_count from public.marketing_send_runs),1,'suppression count stored');
select is((select count(*) from public.marketing_send_recipients),1::bigint,'one immutable recipient');
update public.contacts set first_name='Changed',primary_email='changed@example.test' where id='f3000000-0000-0000-0000-000000000001';
select is((select display_name from public.marketing_send_recipients),'Ada Eligible','snapshot identity immutable');select is((select normalized_email from public.marketing_send_recipients),'ada@example.test','snapshot email normalized and immutable');
select is((public.confirm_campaign_send((select public_id from public.marketing_campaigns),'1234567890abcdef',true)).id,(select id from public.marketing_send_runs),'confirmation idempotent');select is((select count(*) from public.marketing_send_runs),1::bigint,'retry creates no run');
select throws_ok($$select public.confirm_campaign_send((select public_id from public.marketing_campaigns),'abcdef1234567890',true)$$,'22023','Campaign is not ready to send.','invalid transition fails closed');
update public.contacts set marketing_email_status='opted-out' where id='f3000000-0000-0000-0000-000000000001';
select is((select status::text from public.claim_campaign_recipients((select public_id from public.marketing_send_runs),10,'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa')),'suppressed','unsubscribe after snapshot skips delivery');
select is((select eligibility_reason from public.marketing_send_recipients),'consent-changed-before-delivery','skip reason stored');
select is((select count(*) from public.claim_campaign_recipients((select public_id from public.marketing_send_runs),10,'bbbbbbbb-bbbb-bbbb-bbbb-bbbbbbbbbbbb')),0::bigint,'claimed work cannot be reclaimed');
select lives_ok($$select public.register_marketing_unsubscribe_token((select public_id from public.marketing_send_recipients),'digest-one')$$,'opaque token registered');
select ok(public.unsubscribe_marketing('digest-one'),'unsubscribe succeeds');select ok(public.unsubscribe_marketing('digest-one'),'unsubscribe idempotent');select ok(not public.unsubscribe_marketing('missing'),'unknown token reveals nothing');
update public.contacts set marketing_email_status='opted-in' where id='f3000000-0000-0000-0000-000000000001';
select ok(public.record_marketing_delivery_event((select public_id from public.marketing_send_recipients),'test','evt-hard','m1','hard-bounce',now(),'{}'),'hard bounce event accepted');select is((select marketing_email_status::text from public.contacts where id='f3000000-0000-0000-0000-000000000001'),'suppressed','hard bounce suppresses');select ok(not public.record_marketing_delivery_event((select public_id from public.marketing_send_recipients),'test','evt-hard','m1','hard-bounce',now(),'{}'),'provider event idempotent');
update public.contacts set marketing_email_status='opted-in' where id='f3000000-0000-0000-0000-000000000001';select ok(public.record_marketing_delivery_event((select public_id from public.marketing_send_recipients),'test','evt-soft','m1','soft-bounce',now(),'{}'),'soft bounce event accepted');select is((select marketing_email_status::text from public.contacts where id='f3000000-0000-0000-0000-000000000001'),'opted-in','transient failure does not revoke consent');select ok(public.record_marketing_delivery_event((select public_id from public.marketing_send_recipients),'test','evt-complaint','m1','complaint',now(),'{}'),'complaint event accepted');select is((select marketing_email_status::text from public.contacts where id='f3000000-0000-0000-0000-000000000001'),'suppressed','complaint suppresses future marketing');
select set_config('request.jwt.claim.sub','f0000000-0000-0000-0000-000000000002',true);select is((select count(*) from public.marketing_send_runs),0::bigint,'tenant isolation');select * from finish();rollback;
